import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find the positions where a differs from the sorted version
    sorted_a = sorted(a)
    mismatched = [i for i in range(n) if a[i] != sorted_a[i]]

    if len(mismatched) == 0:
        # Already sorted, 0 swaps needed
        print("YES")
    elif len(mismatched) == 2:
        # Check if swapping these two positions fixes it
        i, j = mismatched
        # Swap and check
        a[i], a[j] = a[j], a[i]
        if a == sorted_a:
            print("YES")
        else:
            print("NO")
    else:
        # More than 2 mismatches, cannot fix with 1 swap
        print("NO")

if __name__ == "__main__":
    solve()
"}

