def length_of_lis(nums):
    """Find the length of the longest increasing subsequence using binary search."""
    tails = []
    for num in nums:
        # Find the first index in tails where tails[i] >= num
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] >= num:
                right = mid
            else:
                left = mid + 1
        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num
    return len(tails)

