def longest_increasing_subsequence_length(arr):
    """Find the length of the longest increasing subsequence in arr using O(n log n) algorithm."""
    dp = []  # dp[i] will store the smallest tail of an increasing subsequence of length i+1
    for num in arr:
        # Find the first index in dp where dp[index] >= num
        left, right = 0, len(dp)
        while left < right:
            mid = (left + right) // 2
            if dp[mid] >= num:
                right = mid
            else:
                left = mid + 1

        # If found, replace that element with num
        # If not found, append num to dp
        if left == len(dp):
            dp.append(num)
        else:
            dp[left] = num

    return len(dp)

# Read input
n = int(input())
a = list(map(int, input().split()))

# Compute and print the answer
print(longest_increasing_subsequence_length(a))
