def get_primes_up_to(n):
    """Sieve of Eratosthenes to get all primes up to n"""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes


def get_prime_factors(x, primes):
    """Get all prime factors of x"""
    factors = set()
    for p in primes:
        if p * p > x:
            break
        if x % p == 0:
            factors.add(p)
            while x % p == 0:
                x //= p
    if x > 1:
        factors.add(x)
    return factors


def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    idx = 0
    n = int(data[idx])
    idx += 1

    freq = {}
    for _ in range(n):
        x = int(data[idx])
        idx += 1
        freq[x] = freq.get(x, 0) + 1

    # Get all unique numbers
    unique_numbers = list(freq.keys())

    # Find maximum number to get primes up to that
    max_num = max(unique_numbers)

    # Get all primes up to max_num
    primes = get_primes_up_to(max_num)

    # Count prime factors
    cnt = {}
    for x in unique_numbers:
        for p in get_prime_factors(x, primes):
            cnt[p] = cnt.get(p, 0) + freq[x]

    # Process queries
    m = int(data[idx])
    idx += 1

    output = []
    for _ in range(m):
        l = int(data[idx])
        r = int(data[idx + 1])
        idx += 2

        # Sum cnt[p] for all primes p in [l, r]
        total = 0
        for p in primes:
            if l <= p <= r:
                total += cnt.get(p, 0)
        output.append(str(total))

    print('\n'.join(output))

solve()
