def is_valid_permutation(n, p):
    # We'll simulate the process
    occupied = [False] * (n + 1)  # positions 1..n

    for i in range(1, n + 1):
        # Find where number i is placed
        pos = p[i - 1]

        # Calculate r array
        r = [0] * (n + 1)  # r[0] unused
        for j in range(1, n + 1):
            if occupied[j]:
                # If position j is occupied, r_j = r_{j+1}
                r[j] = r[j + 1]
            else:
                # If position j is unoccupied, r_j = j
                r[j] = j

        # Calculate count array
        count = [0] * (n + 1)  # count[0] unused
        for j in range(1, n + 1):
            if r[j] <= n:
                count[r[j]] += 1

        # Find maximum count among unoccupied positions
        max_count = -1
        for t in range(1, n + 1):
            if not occupied[t]:
                if count[t] > max_count:
                    max_count = count[t]

        # Find all positions with this maximum count that are unoccupied
        valid_positions = [t for t in range(1, n + 1) if not occupied[t] and count[t] == max_count]

        # Check if the actual position is valid
        if pos not in valid_positions:
            return False

        # Mark position as occupied
        occupied[pos] = True

    return True

