        # Find maximum count among unoccupied positions
        max_count = -1
        for t in range(1, n + 1):
            if not occupied[t]:
                if count[t] > max_count:
                    max_count = count[t]

        # Find all positions with this maximum count that are unoccupied
        valid_positions = [t for t in range(1, n + 1) if not occupied[t] and count[t] == max_count]

        # Check if the actual position is valid
        if pos not in valid_positions:
            return False

        # Mark position as occupied
        occupied[pos] = True

    return True

