import sys

def solve() -> None:
    binary = sys.stdin.readline().strip()

    # Find all sequences of consecutive '1's
    sequences = []
    start = None

    for i, bit in enumerate(binary):
        if bit == '1':
            if start is None:
                start = i
        else:
            if start is not None:
                sequences.append((start, i - 1))
                start = None

    # Handle the last sequence if there is one
    if start is not None:
        sequences.append((start, len(binary) - 1))

    # Calculate the minimal number of operations
    m = 0
    terms = []

    for start, end in sequences:
        # For a sequence of length (end - start + 1)
        length = end - start + 1

        # Add terms: +2^(start + length) and -2^start
        terms.append(f"+2^{start + length}")
        terms.append(f"-2^{start}")

        # Add terms for the intermediate positions
        for i in range(start + 1, start + length):
            terms.append(f"+2^{i}")

        m += 2 + (length - 1)

    print(m)
    for term in terms:
        print(term)

if __name__ == "__main__":
