def solve():
    n = int(input())
    colors = list(map(int, input().split()))

    # dp[i][j] = minimum seconds to destroy from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gemstone
    for i in range(n):
        dp[i][i] = 1

    # Fill dp table for substrings of length >= 2
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Check if the whole substring is a palindrome
            is_palindrome = True
            for k in range((j - i + 1) // 2):
                if colors[i + k] != colors[j - k]:
                    is_palindrome = False
                    break

            if is_palindrome:
                dp[i][j] = 1
            else:
                # Try all possible splits
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])

                # Try if we can remove from both ends
                if colors[i] == colors[j]:
                    dp[i][j] = min(dp[i][j], dp[i+1][j-1])
                    # Try removing from i to some point, then from i+1 to j
                    dp[i][j] = min(dp[i][j], dp[i+1][j])
                    # Try removing from i to some point, then from i to j-1
                    dp[i][j] = min(dp[i][j], dp[i][j-1])

    print(dp[0][n-1])

solve()
