MOD = 10**9 + 7

# Check if a number is lucky
def is_lucky(num):
    s = str(num)
    return all(c in {'4', '7'} for c in s)

# Count occurrences of each number
from collections import defaultdict
count = defaultdict(int)
for num in a:
    count[num] += 1

# Precompute combinations C(n, k) modulo MOD
max_n = n + 1
fact = [1] * (max_n + 1)
for i in range(1, max_n + 1):
    fact[i] = fact[i-1] * i % MOD
inv_fact = [1] * (max_n + 1)
inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
for i in range(max_n-1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD

# DP: dp[i][j] = number of subsequences of length j using first i elements
# We'll use 1D array to save space
dp = [0] * (k + 1)
dp[0] = 1  # Base case: 1 way to choose a subsequence of length 0

for num in a:
    cnt = count[num]
    if is_lucky(num):
        # Lucky number: we can take 0 or 1 occurrence
        # Take 1 occurrence: dp[j] += dp[j-1] * cnt
        for j in range(k, 0, -1):
            dp[j] = (dp[j] + dp[j-1] * cnt) % MOD
    else:
        # Unlucky number: we can take any subset of occurrences
        # This is more complex
        for j in range(k, -1, -1):
            for t in range(1, cnt + 1):
                if j - t >= 0:
                    dp[j] = (dp[j] + dp[j-t] * comb(cnt, t)) % MOD

print(dp[k] % MOD)
