import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # dp[i][f] = True if it's possible to assign finger f to position i
    dp = [set(range(1, 6)) for _ in range(n)]

    # Position 1: all fingers are possible
    dp[0] = set(range(1, 6))

    for i in range(1, n):
        prev_val = a[i-1]
        curr_val = a[i]

        # Determine the constraint type
        if curr_val < prev_val:
            # Ascending: b_i < b_{i-1}
            constraint = lambda f_prev, f_curr: f_curr < f_prev
        elif curr_val > prev_val:
            # Descending: b_i > b_{i-1}
            constraint = lambda f_prev, f_curr: f_curr > f_prev
        else:
            # Same: b_i ≠ b_{i-1}
            constraint = lambda f_prev, f_curr: f_curr != f_prev

        # Update available fingers for position i
        dp[i] = set()
        for f_prev in dp[i-1]:
            for f_curr in range(1, 6):
                if constraint(f_prev, f_curr):
                    dp[i].add(f_curr)


    # If no valid fingering, output -1
    if not dp[-1]:
        print(-1)
    else:
        # Output any valid sequence
        # We can just pick any finger from each position's available set
        # Since the problem says to output any convenient fingering
        result = []
        for i in range(n):
            result.append(str(dp[i].pop()))
        print(' '.join(result))

if __name__ == '__main__':
    solve()
