        grid = []
        for _ in range(n):
            grid.append(input().strip())

        operations = []
        # Convert grid to list of lists of integers
        grid_int = [[int(c) for c in row] for row in grid]

        # Process each cell from top-left to bottom-right
        for i in range(n):
            for j in range(m):
                if grid_int[i][j] == 1:
                    # Perform operation on (i,j), (i+1,j), (i,j+1)
                    if i+1 < n and j+1 < m:
                        # Flip cells (i,j), (i+1,j), (i,j+1)
                        grid_int[i][j] ^= 1
                        grid_int[i+1][j] ^= 1
                        grid_int[i][j+1] ^= 1
                        operations.append((i+1, j+1, i+2, j+1, i+1, j+2))
                    elif i+1 < n:
                        # Use (i,j), (i,j+1), (i+1,j+1)
                        if j+1 < m:
                            grid_int[i][j] ^= 1
                            grid_int[i][j+1] ^= 1
                            grid_int[i+1][j+1] ^= 1
                            operations.append((i+1, j+1, i+1, j+2, i+2, j+2))
