        table = []
        for i in range(n):
            row = input().strip()
            table.append([int(c) for c in row])

        operations = []

        # Traverse the table row by row
        for i in range(n - 1):
            for j in range(m - 1):
                # If the cell (i, j) is 1, we need to flip it
                if table[i][j] == 1:
                    # Flip cells (i, j), (i, j+1), (i+1, j)
                    operations.append((i + 1, j + 1, i + 1, j + 2, i + 2, j + 1))

                    # Perform the flip
                    table[i][j] ^= 1
                    table[i][j + 1] ^= 1
                    table[i + 1][j] ^= 1

        print(len(operations))
        for op in operations:
