graph = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b = map(int, input().split())
    graph[a].append(b)
    graph[b].append(a)

# Read the desired topics
topics = list(map(int, input().split()))

# Check if the assignment is valid
valid = True
for i in range(1, n + 1):
    t_i = topics[i - 1]
    # Check if any neighbor has the same topic (would conflict)
    for neighbor in graph[i]:
        if topics[neighbor - 1] == t_i:
            valid = False
            break
    if not valid:
        break

if not valid:
    print(-1)
else:
    # Build dependency graph: blog i depends on all neighbors with topic < t_i
    # We need to check if there's a valid topological order
    # We can use a greedy approach: write blogs with topic 1 first, then topic 2, etc.

    # For each blog, determine its dependencies
    dependencies = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        t_i = topics[i - 1]
        for neighbor in graph[i]:
            if topics[neighbor - 1] < t_i:
                dependencies[i].append(neighbor)

    # Use a greedy approach: for each topic level, find blogs that can be written
    result = []

    # We'll use a queue for each topic level
    from collections import deque

    # For topic 1, no dependencies
    queue = [deque() for _ in range(n + 1)]
    for i in range(1, n + 1):
        if topics[i - 1] == 1:
            queue[1].append(i)

    # For each topic level from 1 to n
    for t in range(1, n + 1):
        # Process all blogs with this topic
        while queue[t]:
            blog = queue[t].popleft()
            result.append(blog)

            # For each neighbor of this blog, update their dependencies
            for neighbor in graph[blog]:
                # Neighbor's topic
                t_neighbor = topics[neighbor - 1]

                # If neighbor has topic > t, we need to check if all its dependencies are satisfied
                if t_neighbor > t:
                    # Neighbor depends on blogs with topic t_neighbor-1 that have already been written
                    # But we've only written blogs with topic <= t so far
                    # So we need to check if all of neighbor's dependencies with topic t_neighbor-1 are satisfied

                    # Count how many of neighbor's neighbors with topic t_neighbor-1 have been written
                    count = 0
                    for neighbor_neighbor in graph[neighbor]:
                        if topics[neighbor_neighbor - 1] == t_neighbor - 1 and neighbor_neighbor in result:
                            count += 1

                    # If count equals the number of neighbors with topic t_neighbor-1, then neighbor can be written
                    # Count how many neighbors have topic t_neighbor-1
                    required = 0
                    for neighbor_neighbor in graph[neighbor]:
                        if topics[neighbor_neighbor - 1] == t_neighbor - 1:
                            required += 1

                    if count == required:
                        queue[t_neighbor].append(neighbor)

    if len(result) == n:
        print(' '.join(map(str, result)))
    else:
        print(-1)
