        sys.stdout.flush()
        response = input().strip()

        if response == "yes":
            # Check if the number is exactly p
            if p == 2:
                print("prime")
            else:
                print("composite")
            sys.stdout.flush()
            return

    # If no divisors found, it's prime
    print("prime")
    sys.stdout.flush()

