        for col in range(1, 3):
            # Check if this cell is already reclaimed
            if (row, col) in state:
                continue

            # Check if this move is valid
            valid = True
            for dr, dc in [(-1, 1), (0, 1), (1, 1)]:
                r2, c2 = row + dr, col + dc
                if 1 <= r2 <= r and (r2, c2) in state:
                    valid = False
                    break
            if not valid:
                continue

            # Make this move
            new_state = set(state)
            new_state.add((row, col))

            # Check if there are any valid moves left after this move
            has_moves = False
            for r2 in range(1, r + 1):
                for c2 in range(1, 3):
                    if (r2, c2) not in new_state:
                        # Check if this cell can be reclaimed
                        can_reclaim = True
                        for dr2, dc2 in [(-1, 1), (0, 1), (1, 1)]:
                            r3, c3 = r2 + dr2, c2 + dc2
                            if 1 <= r3 <= r and (r3, c3) in new_state:
