def count_rhombuses(n, edges):
    graph = [[] for _ in range(n + 1)]
    for a, b in edges:
        graph[a].append(b)

    # For each pair (a, c), find nodes b such that a->b and b->c
    result = 0
    for a in range(1, n + 1):
        for c in range(1, n + 1):
            if a == c:
                continue
            # Find all nodes b that have edges a->b and b->c
            b_list = []
            for b in graph[a]:
                if c in graph[b]:
                    b_list.append(b)
            # Count pairs (b, d) where b != d
            count = len(b_list) * (len(b_list) - 1) // 2
            result += count
    return result

