def count_rhombuses(n, edges):
    # Adjacency matrix
    adj = [[False] * (n + 1) for _ in range(n + 1)]
    for a, b in edges:
        adj[a][b] = True

    # For each pair (a, c), find nodes b such that a->b and b->c
    result = 0
    for a in range(1, n + 1):
        for c in range(1, n + 1):
            if a == c:
                continue
            # Count common neighbors
            count = 0
            for b in range(1, n + 1):
                if adj[a][b] and adj[b][c]:
                    count += 1
            # Add rhombuses
            result += count * (count - 1) // 2
    return result

