def solve():
    n = len(c)
    if n == 0:
        return 0

    # dp[i][j] = min operations to remove gems from i to j (inclusive)
    dp = [[0] * n for _ in range(n)]

    # Base case: single gem
    for i in range(n):
        dp[i][i] = 1

    # Fill dp for substrings of length > 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try all splits
            dp[i][j] = float('inf')
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])

            # If first and last colors match, try removing inner part first
            if c[i] == c[j]:
                dp[i][j] = min(dp[i][j], dp[i+1][j-1])

    return dp[0][n-1]

print(solve())
