from collections import deque

def solve():
    # Read input
    r, c = map(int, input().split())
    grid = []
    start = None
    end = None

    for i in range(r):
        row = list(input().strip())
        grid.append(row)

        for j in range(c):
            if row[j] == 'S':
                start = (i, j)
            if row[j] == 'E':
                end = (i, j)

    # Find shortest path from start to end (ignoring breeders for now)
    # Use BFS
    visited = [[False] * c for _ in range(r)]
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited[start[0]][start[1]] = True

    while queue:
        row, col, dist = queue.popleft()

        if (row, col) == end:
            # Found shortest path
            break

        # Try all four directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < r and 0 <= nc < c and not visited[nr][nc] and grid[nr][nc] != 'T':
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    # Now, for each cell on the path, count breeders within distance t
    # We need to backtrack to find the path
    path = []
    current = end
    while current != start:
        path.append(current)
        # Find predecessor
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < r and 0 <= nc < c and visited[nr][nc]:
                current = (nr, nc)
                break
        path.append(start)

    path.reverse()

    # Calculate total battles
    total_battles = 0

    for i, (row, col) in enumerate(path):
        # Count breeders at distance <= i from this cell
        count = 0
        for dr in range(-i, i + 1):
            for dc in range(-i, i + 1):
                if dr == 0 and dc == 0:
                    continue
                if 0 <= row + dr < r and 0 <= col + dc < c:
                    if grid[row + dr][col + dc].isdigit():
                        count += int(grid[row + dr][col + dc])

        total_battles += count

    print(total_battles)

solve()
