    for i in range(n):
        for j in range(i + 1, n):
            a = denominations[i]
            b = denominations[j]

            # Try using denomination a first
            for c in range(0, min(k, x // a) + 1):
                remainder = x - c * a
                if remainder < 0:
                    break
                if remainder % b == 0:
                    d = remainder // b
                    if c + d <= k:
                        min_bills = min(min_bills, c + d)

    if min_bills != float('inf'):
        results.append(str(min_bills))
    else:
        results.append("-1")

