    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Create sorted version of the array
    sorted_a = sorted(a)

    # Find positions where elements differ
    diffs = []
    for i in range(n):
        if a[i] != sorted_a[i]:
            diffs.append(i)

    # Check if we can sort with at most 1 swap
    if len(diffs) == 0:
        print("YES")
    elif len(diffs) == 2:
        # Check if swapping these two positions would sort the array
        i, j = diffs
        # Swap a[i] and a[j] and check if it matches sorted_a
        a[i], a[j] = a[j], a[i]
        if a == sorted_a:
            print("YES")
        else:
            print("NO")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
