def max_game_result(n, memo={}):
    """Calculate the maximum game result starting from n."""
    if n == 1:
        return 1

    # Check if we've already computed this value
    if n in memo:
        return memo[n]

    # Find all divisors of n (excluding n itself)
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Add n itself as a possible divisor (when we take all pebbles in one row)
    divisors.add(n)

    # Try all valid moves
    max_result = 0
    for divisor in divisors:
        if divisor < n:
            result = n + max_game_result(divisor, memo)
            if result > max_result:
                max_result = result

    memo[n] = max_result
    return max_result

# Read input
n = int(input())

# Calculate and print result
print(max_game_result(n))
"}

