def solve():
    binary = sys.stdin.readline().strip()

    # Find groups of consecutive 1s
    groups = []
    i = 0
    while i < len(binary):
        if binary[i] == '1':
            j = i
            while j < len(binary) and binary[j] == '1':
                j += 1
            groups.append((i, j - i))  # (position, length)
            i = j
        else:
