    # Calculate minimal terms
    terms = []
    for position, length in groups:
        if length == 1:
            terms.append(f"+2^{position}")
        else:
            terms.append(f"+2^{position + length}")
            terms.append(f"-2^{position}")

    # Output
    print(len(terms))
    for term in terms:
        print(term)

