import sys

def solve():
    binary = sys.stdin.readline().strip()

    # Find groups of consecutive 1s
    groups = []
    i = 0
    while i < len(binary):
        if binary[i] == '1':
            j = i
            while j < len(binary) and binary[j] == '1':
                j += 1
            # The group starts at position (len(binary) - 1 - i)
            # because we're counting from the right
            position = len(binary) - 1 - i
            length = j - i
            groups.append((position, length))
            i = j
        else:
            i += 1

    # Calculate minimal terms
    terms = []
    for position, length in groups:
        if length == 1:
            terms.append(f"+2^{position}")
        else:
            # +2^(position + length) - 2^position
