import math

def solve():
    n = int(input())
    volumes = []

    for _ in range(n):
        r, h = map(int, input().split())
        volumes.append(math.pi * r * r * h)

    # dp[i] is the maximum volume ending with cake i (original index order)
    dp = [0] * n

    for i in range(n):
        dp[i] = volumes[i]  # At least we can just use this cake alone

        # Check all previous cakes
        for j in range(i):
            if volumes[i] > volumes[j]:  # Volume i > Volume j
                if dp[j] + volumes[i] > dp[i]:
                    dp[i] = dp[j] + volumes[i]

    print(max(dp))

