import sys
from math import isqrt

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    arr = []
    max_val = 0
    for _ in range(n):
        x = int(next(it))
        arr.append(x)
        if x > max_val:
            max_val = x

    m = int(next(it))
    queries = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        queries.append((l, r))

    # Count frequencies
    freq = {}
    for x in arr:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1

    # Find prime divisors for each number up to max_val
    prime_divisors = [[] for _ in range(max_val + 1)]

    # Sieve of Eratosthenes to find primes
    is_prime = [True] * (max_val + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, isqrt(max_val) + 1):
        if is_prime[i]:
            for j in range(i * i, max_val + 1, i):
                is_prime[j] = False

    # For each prime, mark its multiples
    for p in range(2, max_val + 1):
        if is_prime[p]:
            for multiple in range(p, max_val + 1, p):
                prime_divisors[multiple].append(p)

    # Count occurrences of each prime
    prime_count = {}
    for x in freq:
        for p in prime_divisors[x]:
            prime_count[p] = prime_count.get(p, 0) + freq[x]

    # Create prefix sums for primes
    prefix = [0] * (max_val + 2)
    for i in range(2, max_val + 1):
        prefix[i] = prefix[i - 1] + (prime_count.get(i, 0))

    # Answer queries
    output = []
    for l, r in queries:
        # Sum of primes in [l, r]
        # This is prefix[r] - prefix[l-1]
        if l == 0:
            ans = prefix[r]
        else:
            ans = prefix[r] - prefix[l - 1]
        output.append(str(ans))

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
