def find_min_replacement(password):
    n = len(password)

    # Check if already valid
    if is_valid(password):
        return password, 0

    # Try to find the minimal length replacement
    # First check if we need a digit
    if not any(c.isdigit() for c in password):
        # Need at least one digit
        for length in range(1, n + 1):
            for i in range(n - length + 1):
                # Replace substring from i to i+length-1 with a digit
                new_pass = password[:i] + '0' + password[i+length:]
                if is_valid(new_pass):
                    return new_pass, length
        return password, 0

    # First check if we need uppercase
    if not any(c.isupper() for c in password):
        # Need at least one uppercase
        for length in range(1, n + 1):
            for i in range(n - length + 1):
                # Replace substring from i to i+length-1 with uppercase
                new_pass = password[:i] + 'A' + password[i+length:]
                if is_valid(new_pass):
                    return new_pass, length
        return password, 0

    # First check if we need lowercase
    if not any(c.islower() for c in password):
