    min_bills = float('inf')

    # Try each denomination
    for a in denominations:
        if x % a == 0 and x // a <= k:
            min_bills = min(min_bills, x // a)

    # Check using two denominations
    for i in range(n):
        for j in range(i + 1, n):
            a1 = denominations[i]
            a2 = denominations[j]

            # Try all possible counts of the first denomination
            max_c1 = min(k, x // a1)
            for c1 in range(max_c1 + 1):
