        for c1 in range(1, total_bills):
            c2 = total_bills - c1

            # Try all pairs of denominations
            for i in range(n):
                for j in range(i + 1, n):
                    a1 = denominations[i]
                    a2 = denominations[j]

                    # Check if we can make x with c1 of a1 and c2 of a2
                    if c1 * a1 + c2 * a2 == x:
                        min_bills = min(min_bills, total_bills)

    if min_bills != float('inf'):
        results.append(str(min_bills))
    else:
        results.append('-1')

print('\n'.join(results))

