n, m = map(int, input().split())

# Read the graph
graph = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b = map(int, input().split())
    graph[a].append(b)
    graph[b].append(a)

# Read desired topics
topics = list(map(int, input().split()))

# Build constraint graph
# If t_u < t_v, u must come before v
constraint_graph = [[] for _ in range(n + 1)]
indegree = [0] * (n + 1)

for u in range(1, n + 1):
    for v in graph[u]:
        if topics[u - 1] < topics[v - 1]:
            constraint_graph[u].append(v)
            indegree[v] += 1
        elif topics[v - 1] < topics[u - 1]:
            constraint_graph[v].append(u)
            indegree[u] += 1

# Find topological sort using Kahn's algorithm
queue = deque()
for i in range(1, n + 1):
    if indegree[i] == 0:
        queue.append(i)

order = []
while queue:
    current = queue.popleft()
    order.append(current)
    for neighbor in constraint_graph[current]:
        indegree[neighbor] -= 1
        if indegree[neighbor] == 0:
            queue.append(neighbor)

if len(order) != n:
    print(-1)
else:
    print(' '.join(map(str, order)))
