import sys

def solve():
    input_str = sys.stdin.read().strip()
    lines = input_str.split('\n')

    if not lines:
        return

    data = lines[0].split()

    if not data:
        return

    r = int(data[0])
    c = int(data[1])

    # Read the grid rows
    grid = []
    idx = 2

    for i in range(r):
        if idx + i >= len(lines):
            break
        row = lines[idx + i]
        grid.append(row)

    # Find start (S) and exit (E) positions
    start = None
    exit_pos = None
    breeders = {}

    for i in range(r):
        for j in range(c):
            char = grid[i][j]
            if char == 'S':
                start = (i, j)
            elif char == 'E':
                exit_pos = (i, j)
            elif '0' <= char <= '9':
                breeders[(i, j)] = int(char)

    # BFS to find shortest path from S to E
    def bfs(start, exit_pos):
        dist = [[-1] * c for _ in range(r)]
        q = [(start[0], start[1])]
        dist[start[0]][start[1]] = 0

        while q:
            x, y = q.pop(0)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] != 'T' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

        return dist

    dist = bfs(start, exit_pos)

    # Find the shortest path (any one)
    path = []
    x, y = exit_pos
    while dist[x][y] != 0:
        path.append((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] != 'T' and dist[nx][ny] == dist[x][y] - 1:
                x, y = nx, ny
                break
    path.append(start)
    path.reverse()

    # Calculate how many breeders can reach each cell on the path
    max_breeders = 0

    for i, (x, y) in enumerate(path):
        count = 0
        for (bx, by), bnum in breeders.items():
            # Can breeder at (bx, by) reach (x, y) in <= dist[x][y] moves?
