def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    data = iter(input)
    n = int(next(data))
    m = int(next(data))

    # Build graph
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = int(next(data))
        b = int(next(data))
        graph[a].append(b)
        graph[b].append(a)

    # Read topics
    topics = [0] + [int(next(data)) for _ in range(n)]

    # Check if the topic assignment is valid
    for i in range(1, n + 1):
        t = topics[i]

        # Check if there's a neighbor with the same topic
        for j in graph[i]:
            if topics[j] == t:
                print(-1)
                return

        # Check if it has all smaller topics
        for k in range(1, t):
            has_topic = False
            for j in graph[i]:
                if topics[j] == k:
                    has_topic = True
                    break
            if not has_topic:
                print(-1)
                return


    # Build in-degree array (nodes with smaller topics)
    in_degree = [0] * (n + 1)

    # For each blog, count how many neighbors have smaller topics
    for i in range(1, n + 1):
        for j in graph[i]:
            if topics[j] < topics[i]:
                in_degree[i] += 1

    # Topological sort
    from collections import deque

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
