        count += 1
    # Check if we might loop infinitely
    if abs(q) == 1:
        # Should have handled this earlier
        break
    # Check if we might start repeating
    if abs(current) < l and abs(q) < 1:
        # Terms will get smaller, eventually exceed l
        # But we need to check if we might enter a loop
        # If q=0, terms become 0, then stay 0
        if q == 0:
            break
    current *= q

