def max_game_result(n):
    """Calculate the maximum possible result of the game."""
    # Base case: if we have 1 pebble, the game ends
    if n == 1:
        return 1

    # Find all divisors a > 1 of n
    divisors = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)

    # Also consider the case where we take all but one pebble (a = n-1, b = 2)
    # This is equivalent to taking one row with 2 pebbles
    divisors.append(n - 1)

    # Sort divisors to ensure we get the maximum result
    divisors = sorted(divisors)

    # Use memoization to store results of subproblems
    memo = {}

    def f(x):
        if x in memo:
            return memo[x]

        # Find all divisors a > 1 of x
        divisors_x = []
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                divisors_x.append(i)
                if i != x // i:
                    divisors_x.append(x // i)

        # Also consider the case where we take all but one pebble
        divisors_x.append(x - 1)

        # Calculate the maximum result
        max_result = 1  # Minimum result is when we end immediately
        for a in divisors_x:
            b = x // a
            result = x + f(b)
            if result > max_result:
                max_result = result

        memo[x] = max_result
        return max_result

    return f(n)

# Read input and output result
n = int(input())
print(max_game_result(n))
