n, m = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b = map(int, input().split())
    adj[a].append(b)

# For each pair (a, c), count rhombi
rhombi_count = 0

for a in range(1, n + 1):
    for c in range(1, n + 1):
        if a == c:
            continue  # Skip if a and c are the same node

        # Find all b such that a->b and b->c
        b_set = set()
        for b in adj[a]:
            if c in adj[b]:
                b_set.add(b)

        # Find all d such that a->d and d->c
        d_set = set()
        for d in adj[a]:
            if c in adj[d]:
                d_set.add(d)

        # Count pairs (b, d) where b != d
        intersection = b_set & d_set
        rhombi_count += len(b_set) * len(d_set) - min(len(intersection), 1)

# Each rhombus is counted twice (once for (a,c) and once for (c,a))
rhombi_count //= 2

print(rhombi_count)
