    even_count = 0
    odd_count = 0
    for j in range(i, n):
        if a[j] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
        if even_count == odd_count:
            valid_segments.append((i, j))

# DP: dp[i][k] = minimum cost to achieve k cuts for the first i elements
INF = float('inf')
dp = [[INF] * (n + 1) for _ in range(n + 1)]
dp[0][0] = 0

for i in range(n):
    for k in range(n + 1):
        if dp[i][k] == INF:
            continue
        # Make a cut at position i (between i and i+1)
        if i + 1 < n:
            cost = abs(a[i] - a[i + 1])
            if k + 1 <= n:
                dp[i + 1][k + 1] = min(dp[i + 1][k + 1], dp[i][k] + cost)

# Find the maximum number of cuts
max_cuts = 0
for k in range(n + 1):
    if dp[n][k] <= B:
        max_cuts = k

print(max_cuts)
