import sys
import math

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    arr = [int(next(it)) for _ in range(n)]

    # Count frequency of each number
    freq = {}
    for x in arr:
        freq[x] = freq.get(x, 0) + 1

    # Precompute smallest prime factors (SPF) up to 10^7
    max_x = max(arr)
    spf = list(range(max_x + 1))

    for i in range(2, int(math.sqrt(max_x)) + 1):
        if spf[i] == i:
            for j in range(i * i, max_x + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Find all primes up to 10^7
    primes = []
    for i in range(2, max_x + 1):
        if spf[i] == i:
            primes.append(i)

    # Count how many numbers are divisible by each prime
    count = [0] * (max_x + 1)

    for x in arr:
        # Get prime factors of x
        p_factors = set()
        temp = x
        while temp > 1:
            p = spf[temp]
            p_factors.add(p)
            while temp % p == 0:
                temp //= p

        # Add to counts
        for p in p_factors:
            count[p] += freq[x]

    # Create prefix sums for primes
    prefix = [0] * (len(primes) + 1)
    for i in range(len(primes)):
        prefix[i + 1] = prefix[i] + count[primes[i]]

    # Process queries
    m = int(next(it))
    out_lines = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))

        # Binary search for left and right bounds
        left = bisect.bisect_left(primes, l)
        right = bisect.bisect_right(primes, r) - 1

        if left > right:
            out_lines.append('0')
        else:
            out_lines.append(str(prefix[right + 1] - prefix[left]))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
