    visited = [False] * (n + 1)
    cycles = 0
    for i in range(1, n + 1):
        if not visited[i]:
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = p[current - 1]  # convert to 0-indexed

    # Count number of 1s in b
    ones = b.count(1)

    # If there's only 1 cycle, we need at least 1 one
    if cycles == 1:
        if ones >= 1:
            print(0)
        else:
            print(1)
    else:
        # If there are multiple cycles, we need cycles - 1 changes to p
        # We also need at least 1 one
        if ones >= 1:
            print(cycles - 1)
        else:
            print(cycles - 1 + 1)

