n = int(input())
c = list(map(int, input().split()))

# Initialize DP table
dp = [[0] * n for _ in range(n)]

# Base case: single gemstone
for i in range(n):
    dp[i][i] = 1

# Fill DP table for subarrays of length >= 2
for length in range(2, n + 1):
    for i in range(n - length + 1):
        j = i + length - 1

        # If first and last are the same, we can potentially remove them together
        if c[i] == c[j]:
            dp[i][j] = dp[i+1][j-1]
        else:
            dp[i][j] = float('inf')

        # Try all possible splits
        for k in range(i, j):
            dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])

print(dp[0][n-1])
