n, k, x = map(int, input().split())
a = list(map(int, input().split()))

# Calculate initial OR
or_val = 0
for num in a:
    or_val |= num

# Try to set each bit from highest to lowest
for bit in range(30, -1, -1):
    # Try to set this bit
    new_or = or_val | (1 << bit)

    # Calculate how many operations each number would take to set this bit
    ops_needed = []
    for num in a:
        if num & (1 << bit):
            # This bit is already set, no operations needed
            ops_needed.append(0)
        else:
            # Calculate how many operations to set this bit
            ops = 0
            temp = num
            while not (temp & (1 << bit)):
                temp *= x
                ops += 1
            ops_needed.append(ops)

    # Try to set the bit using at most k operations
    # Try all combinations of numbers to operate on
    # Since k is small (≤ 10), we can use bitmasking
    max_set = 0
    for mask in range(1 << n):
        total_ops = 0
        for i in range(n):
            if (mask >> i) & 1:
                total_ops += ops_needed[i]
        if total_ops <= k:
            max_set = max(max_set, (1 << bit))

    if max_set:
        or_val = new_or

