def max_game_result(n):
    # Base case: if we have 1 pebble, the game ends
    if n == 1:
        return 1

    # Find all divisors of n (excluding n itself)
    divisors = []
    for i in range(2, n):
        if n % i == 0:
            divisors.append(i)

    # If no divisors found, we can't make a move (only possible if n is prime)
    if not divisors:
        return n + 1  # We have n, then take 1 pebble to end

    # Try all divisors and choose the one that maximizes the result
    max_result = 0
    for divisor in divisors:
        result = n + max_game_result(divisor)
        if result > max_result:
            max_result = result

    return max_result

