import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    p = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1

    freq = {}
    for _ in range(n):
        a = int(data[idx]); idx += 1
        b = (pow(a, 4, p) - k * a) % p
        freq[b] = freq.get(b, 0) + 1

    ans = 0
    for count in freq.values():
        ans += count * (count - 1) // 2

    print(ans)

